import Foundation
import UIKit
import UniformTypeIdentifiers
import Testing
@testable import PocketPrint

private final class BundleToken {}

/// Byte streams generated by the TiMini-Print reference encoder (Apache-2.0) for Tiny Print's
/// `d1` profile, which is what the vendor app uses for "P1-xxxx" printers.
private func golden(_ key: String) throws -> Data {
    let url = try #require(Bundle(for: BundleToken.self).url(forResource: "tiny_d1_golden", withExtension: "json"))
    let table = try JSONDecoder().decode([String: String].self, from: Data(contentsOf: url))
    let hex = try #require(table[key])
    var bytes: [UInt8] = []
    var index = hex.startIndex
    while index < hex.endIndex {
        let next = hex.index(index, offsetBy: 2)
        bytes.append(UInt8(hex[index..<next], radix: 16)!)
        index = next
    }
    return Data(bytes)
}

private func raster(_ kind: String, height: Int) -> MonoBitmap {
    let width = 384
    var pixels = [UInt8](repeating: 0, count: width * height)
    for y in 0..<height {
        for x in 0..<width {
            let black: Bool
            switch kind {
            case "pattern": black = (x * 7 + y * 13) % 11 < 4
            case "bars": black = (x / 32) % 2 == 0
            default: black = (y % 3 == 0 && x < 200) || (y % 3 == 1 && x % 2 == 0)
            }
            pixels[y * width + x] = black ? 1 : 0
        }
    }
    return MonoBitmap(width: width, height: height, pixels: pixels)
}

private func options(text: Bool, energy: UInt16, compress: Bool) -> TinyJobOptions {
    var options = TinyJobOptions()
    options.isTextMode = text
    options.energy = energy
    options.compress = compress
    return options
}

struct TinyProtocolTests {
    @Test func crcMatchesStandardCheckValue() throws {
        #expect(TinyProtocol.crc8(Array("123456789".utf8)) == 0xF4)
        #expect(try golden("crc_123456789") == Data([0xF4]))
    }

    @Test func flowControlFramesHaveKnownChecksums() {
        #expect(TinyProtocol.packet(0xAE, [0x10]) == [0x51, 0x78, 0xAE, 0x00, 0x01, 0x00, 0x10, 0x70, 0xFF])
        #expect(TinyProtocol.blackening(3) == [0x51, 0x78, 0xA4, 0x00, 0x01, 0x00, 0x33, 0x99, 0xFF])
        #expect(TinyProtocol.energy(5000) == [0x51, 0x78, 0xAF, 0x00, 0x02, 0x00, 0x88, 0x13, 0x67, 0xFF])
        #expect(TinyProtocol.energy(0).isEmpty)
    }

    @Test(arguments: [
        ("pattern_5_image_rle", "pattern", 5, false, UInt16(5000), true),
        ("bars_4_text_rle", "bars", 4, true, UInt16(8000), true),
        ("mixed_203_image_rle", "mixed", 203, false, UInt16(5000), true),
        ("mixed_3_image_raw", "mixed", 3, false, UInt16(5000), false),
    ])
    func jobMatchesReferenceEncoder(key: String, kind: String, height: Int, text: Bool, energy: UInt16, compress: Bool) throws {
        let encoded = TinyProtocol.encodeJob(raster(kind, height: height), options: options(text: text, energy: energy, compress: compress))
        #expect(encoded == (try golden(key)))
    }

    @Test func prefixedDialectOnlyChangesThePrefix() {
        var prefixed = TinyJobOptions()
        prefixed.dialect = .prefixed
        let bitmap = raster("bars", height: 2)
        let standard = TinyProtocol.encodeJob(bitmap, options: TinyJobOptions())
        let other = TinyProtocol.encodeJob(bitmap, options: prefixed)
        let restored = Data(other).replacingOccurrences(of: Data([0x12, 0x51, 0x78]), with: Data([0x51, 0x78]))
        #expect(restored == standard)
    }

    @Test func runLengthEncodingSplitsLongRuns() {
        var row = [UInt8](repeating: 0, count: 384)
        row.withUnsafeBufferPointer { #expect(TinyProtocol.runLengthEncode($0) == [127, 127, 127, 3]) }
        for i in 0..<200 { row[i] = 1 }
        row.withUnsafeBufferPointer { #expect(TinyProtocol.runLengthEncode($0) == [0xFF, 0x80 | 73, 127, 57]) }
    }

    @Test func rowsArePackedLeastSignificantBitFirst() {
        var row = [UInt8](repeating: 0, count: 16)
        row[0] = 1
        row[9] = 1
        row.withUnsafeBufferPointer { #expect(TinyProtocol.packRow($0) == [0x01, 0x02]) }
    }
}

struct NotificationDecoderTests {
    @Test func decodesPauseAndResumeAcrossFragments() {
        var decoder = TinyStreamDecoder()
        #expect(decoder.feed(Data([0x00, 0x51, 0x78, 0xAE, 0x01])).isEmpty)
        let packets = decoder.feed(Data([0x01, 0x00, 0x10, 0x70, 0xFF, 0x51, 0x78, 0xAE, 0x01, 0x01, 0x00, 0x00, 0x00, 0xFF]))
        #expect(packets == [TinyPacket(command: 0xAE, flags: 1, payload: [0x10]), TinyPacket(command: 0xAE, flags: 1, payload: [0x00])])
    }

    @Test func skipsCorruptFrames() {
        var decoder = TinyStreamDecoder()
        let corrupt: [UInt8] = [0x51, 0x78, 0xA3, 0x01, 0x01, 0x00, 0x05, 0x00, 0xFF]
        let valid = TinyProtocol.packet(0xA3, [0x01, 0x40, 0x22])
        let packets = decoder.feed(Data(corrupt + valid))
        #expect(packets == [TinyPacket(command: 0xA3, flags: 0, payload: [0x01, 0x40, 0x22])])
        #expect(PrinterStatusFlags(statusByte: packets[0].payload[0]) == .paperOut)
        #expect(PrinterStatusFlags(statusByte: 0x09) == [.paperOut, .lowBattery])
        #expect(PrinterStatusFlags(statusByte: 0x02) == .coverOpen)
        #expect(PrinterStatusFlags(statusByte: 0x90).isEmpty)
        #expect(PrinterStatusFlags(statusByte: 0x00).messages.isEmpty)
    }

    /// Device-state replies captured from X6h/SC03h printers, which share the P1's table entry.
    @Test(arguments: [
        ([0x51, 0x78, 0xA3, 0x01, 0x03, 0x00, 0x00, 0x04, 0x24, 0xA8, 0xFF] as [UInt8], 33),
        ([0x51, 0x78, 0xA3, 0x01, 0x03, 0x00, 0x00, 0x12, 0x27, 0x88, 0xFF] as [UInt8], 83),
        ([0x51, 0x78, 0xA3, 0x01, 0x03, 0x00, 0x00, 0x15, 0x29, 0xC9, 0xFF] as [UInt8], 100),
    ])
    func decodesBatteryFromCapturedReplies(frame: [UInt8], percent: Int) throws {
        var decoder = TinyStreamDecoder()
        let packet = try #require(decoder.feed(Data(frame)).first)
        #expect(packet.command == TinyCommand.deviceState)
        let state = DeviceState(payload: packet.payload, hasBatteryGauge: true)
        #expect(state.batteryPercent == percent)
        #expect(state.flags.isEmpty)
        #expect(DeviceState(payload: packet.payload, hasBatteryGauge: false).batteryPercent == nil)
    }

    @Test func batteryGaugeFollowsVendorSixBarScale() {
        let expected: [(UInt8, Int)] = [(0x00, 0), (0x22, 0), (0x23, 17), (0x24, 33), (0x25, 50),
                                        (0x26, 67), (0x27, 83), (0x28, 100), (0x2A, 100), (0xFF, 100)]
        for (gauge, percent) in expected {
            #expect(DeviceState.batteryPercent(gauge: gauge) == percent, "gauge \(gauge)")
        }
        #expect(DeviceState(payload: [0x00, 0x04], hasBatteryGauge: true).batteryPercent == nil)
    }

    @MainActor
    @Test func serviceShowsBatteryOnlyForModelsWithAGauge() throws {
        let reply = Data([0x51, 0x78, 0xA3, 0x01, 0x03, 0x00, 0x00, 0x12, 0x27, 0x88, 0xFF])
        func service(named name: String) throws -> PrinterService {
            let defaults = try #require(UserDefaults(suiteName: "PocketPrintTests.\(UUID().uuidString)"))
            let settings = AppSettings(defaults: defaults)
            settings.lastPrinterName = name
            return PrinterService(settings: settings)
        }

        let p1 = try service(named: "P1-28F2")
        p1.handleNotification(reply)
        #expect(p1.batteryPercent == 83)
        #expect(p1.statusFlags.isEmpty)

        let gb01 = try service(named: "GB01")
        gb01.handleNotification(reply)
        #expect(gb01.batteryPercent == nil)

        let unknown = try service(named: "Thermal-01")
        unknown.handleNotification(reply)
        #expect(unknown.batteryPercent == nil)

        p1.handleNotification(Data(TinyProtocol.packet(0xA3, [0x08, 0x00, 0x23])))
        #expect(p1.batteryPercent == 17)
        #expect(p1.statusFlags == .lowBattery)
    }
}

struct PrinterCatalogTests {
    @Test func detectsP1FromItsBluetoothName() {
        let profile = PrinterCatalog.profile(forDeviceName: "P1-28F2")
        #expect(profile?.id == "d1")
        #expect(profile?.dialect == .standard)
        #expect(profile?.imageEnergy == 5000)
        #expect(profile?.textEnergy == 8000)
        #expect(profile?.imageSpeed == 10)
    }

    @Test func prefersLongestAndCaseExactPrefix() {
        #expect(PrinterCatalog.profile(forDeviceName: "P10-1A2B")?.id == "p10")
        #expect(PrinterCatalog.profile(forDeviceName: "X6h-0001")?.id == "d1")
        #expect(PrinterCatalog.profile(forDeviceName: "X6H-0001")?.id == "x6h")
        #expect(PrinterCatalog.profile(forDeviceName: "GB03")?.id == "gb03_2")
        #expect(PrinterCatalog.profile(forDeviceName: "LY10-77")?.dialect == .prefixed)
        #expect(PrinterCatalog.profile(forDeviceName: "x6h-lower")?.id != nil)
        #expect(PrinterCatalog.profile(forDeviceName: "AirPods Pro") == nil)
        #expect(PrinterCatalog.profile(forDeviceName: nil) == nil)
    }

    @MainActor
    @Test func defaultJobOptionsMatchTinyPrintForP1() throws {
        let defaults = try #require(UserDefaults(suiteName: "PocketPrintTests.\(UUID().uuidString)"))
        let settings = AppSettings(defaults: defaults)
        settings.lastPrinterName = "P1-28F2"
        let service = PrinterService(settings: settings)

        let image = service.jobOptions(isTextMode: false, darkness: 3)
        #expect(image.dialect == .standard)
        #expect(image.energy == 5000)
        #expect(image.speed == 10)
        #expect(image.compress)
        #expect(image.postPrintFeedCount == 2)
        #expect(image.blackening == 3)

        let text = service.jobOptions(isTextMode: true, darkness: 9)
        #expect(text.energy == 8000)
        #expect(text.blackening == 5)

        settings.heat = .darker
        settings.dialectChoice = .prefixed
        let tuned = service.jobOptions(isTextMode: false, darkness: 1)
        #expect(tuned.energy == 6500)
        #expect(tuned.dialect == .prefixed)
    }
}

struct ImagingTests {
    @Test func rotationRoundTripsAndMapsCorners() {
        var bitmap = MonoBitmap(width: 5, height: 3)
        bitmap[0, 0] = true
        bitmap[4, 2] = true
        let clockwise = bitmap.rotated(quarterTurns: 1)
        #expect(clockwise.width == 3 && clockwise.height == 5)
        #expect(clockwise[2, 0])
        #expect(clockwise[0, 4])
        #expect(clockwise.rotated(quarterTurns: 3) == bitmap)
        #expect(bitmap.rotated(quarterTurns: 4) == bitmap)
        #expect(bitmap.rotated(quarterTurns: 2).rotated(quarterTurns: 2) == bitmap)
    }

    @Test func stackingCentresNarrowParts() {
        let narrow = MonoBitmap(width: 4, height: 2, value: 1)
        let stacked = MonoBitmap.stacked([narrow, MonoBitmap(width: 10, height: 1)], width: 10, spacing: 3)
        #expect(stacked.height == 6)
        #expect(stacked[3, 0] && stacked[6, 1] && !stacked[2, 0] && !stacked[7, 0])
    }

    @Test(arguments: [DitherStyle.floydSteinberg, .atkinson, .halftone, .ordered, .threshold])
    func ditheringFollowsBrightness(style: DitherStyle) {
        let width = 128, height = 64
        var gradient = GrayImage(width: width, height: height)
        for y in 0..<height {
            for x in 0..<width { gradient.data[y * width + x] = Float(x) / Float(width - 1) }
        }
        let mono = Dither.apply(gradient, style: style)
        func blackCount(_ columns: Range<Int>) -> Int {
            var count = 0
            for y in 0..<height { for x in columns where mono[x, y] { count += 1 } }
            return count
        }
        #expect(blackCount(0..<32) > blackCount(96..<128) * 3)
        #expect(blackCount(0..<32) > 0)
    }

    @Test func pngRoundTripIsLossless() throws {
        let bitmap = raster("pattern", height: 20)
        let png = try #require(bitmap.pngData())
        #expect(MonoBitmap(pngData: png) == bitmap)
    }

    @Test func wifiQRPayloadEscapesSpecialCharacters() {
        let block = QRBlock(mode: .wifi, wifiSSID: "Home;Net", wifiPassword: "p:ss")
        #expect(block.payload == "WIFI:T:WPA;S:Home\\;Net;P:p\\:ss;;")
        #expect(CodeRaster.qrBitmap(block.payload, maxSize: 300) != nil)
    }

    @Test func designRendererProducesPrintWidthStrip() async {
        let design = Design(title: "Test", blocks: [
            Block(.text(TextBlock(text: "Hello", style: TextStyle(size: 40, bold: true, align: .center)))),
            Block(.checklist(ChecklistBlock(items: [ChecklistItem(text: "Milk", checked: true)]))),
            Block(.qr(QRBlock(text: "https://example.com"))),
            Block(.divider(DividerBlock(style: .wave))),
            Block(.calendar(CalendarBlock(year: 2026, month: 11))),
        ], frame: .ticket, lengthMM: 0)
        let rendered = await DesignRenderer().render(design)
        #expect(rendered.bitmap.width == PrinterCatalog.printWidth)
        #expect(rendered.bitmap.height > 300)
        #expect(!rendered.bitmap.isBlank)
        #expect(rendered.blockRanges.count == design.blocks.count)
        #expect(rendered.isTextMode)
    }

    @Test func fixedLengthLabelsAreExactlyThatLong() async {
        let design = Design(blocks: [Block(.text(TextBlock(text: "Jam", style: TextStyle(size: 40))))], lengthMM: 40)
        let rendered = await DesignRenderer().render(design)
        #expect(rendered.bitmap.height == 320)
    }

    @Test func pdfPagesAreTrimmedRotatedAndFittedToPrintWidth() throws {
        let renderer = UIGraphicsPDFRenderer(bounds: CGRect(x: 0, y: 0, width: 612, height: 792))
        let data = renderer.pdfData { context in
            context.beginPage()
            UIColor.black.setFill()
            UIRectFill(CGRect(x: 200, y: 300, width: 200, height: 100))
            context.beginPage(withBounds: CGRect(x: 0, y: 0, width: 800, height: 400), pageInfo: [:])
            UIRectFill(CGRect(x: 0, y: 0, width: 800, height: 400))
        }
        let source = DocumentSource(pdfData: data)
        #expect(source.pages.count == 2)

        let trimmed = try #require(source.gray(page: 0, rotateLandscape: true, trimMargins: true))
        #expect(trimmed.width == PrinterCatalog.printWidth)
        // A 2:1 black box with a small margin stays roughly 2:1 after trimming.
        #expect(abs(Double(trimmed.height) / Double(trimmed.width) - 0.5) < 0.1)

        let landscape = try #require(source.gray(page: 1, rotateLandscape: true, trimMargins: false))
        #expect(landscape.width == PrinterCatalog.printWidth)
        #expect(landscape.height == PrinterCatalog.printWidth * 2)

        let composed = DocumentComposer.compose(source, options: DocumentOptions(pages: [0, 1]))
        #expect(composed.width == PrinterCatalog.printWidth)
        #expect(composed.height > trimmed.height + landscape.height)
        #expect(!composed.isBlank)
    }
}

struct ClipboardTests {
    private func pngProvider(width: Int = 60, height: Int = 40) -> NSItemProvider {
        let format = UIGraphicsImageRendererFormat()
        format.scale = 1
        let png = UIGraphicsImageRenderer(size: CGSize(width: width, height: height), format: format).pngData { context in
            UIColor.black.setFill()
            context.fill(CGRect(x: 0, y: 0, width: width / 2, height: height))
        }
        return NSItemProvider(item: png as NSData, typeIdentifier: UTType.png.identifier)
    }

    @Test func singlePictureIsSavedForEditing() async throws {
        let content = await ClipboardReader.load([pngProvider()])
        guard case .images(let ids) = content else {
            Issue.record("Expected a picture, got \(String(describing: content))")
            return
        }
        #expect(ids.count == 1)
        let image = try #require(ImageStore.shared.cgImage(for: ids[0]))
        #expect(image.width == 60 && image.height == 40)
    }

    @Test func severalPicturesKeepTheirOrderUpToTheLimit() async {
        let providers = (0..<(ClipboardReader.maxImages + 3)).map { pngProvider(width: 20 + $0, height: 20) }
        guard case .images(let ids) = await ClipboardReader.load(providers) else {
            Issue.record("Expected pictures")
            return
        }
        #expect(ids.count == ClipboardReader.maxImages)
        #expect(ids.compactMap { ImageStore.shared.cgImage(for: $0)?.width } == Array(20..<(20 + ClipboardReader.maxImages)))
    }

    @Test func picturesWinOverTheLinkCopiedWithThem() async {
        let link = NSItemProvider(object: "https://example.com/cat.png" as NSString)
        guard case .images(let ids) = await ClipboardReader.load([link, pngProvider()]) else {
            Issue.record("Expected a picture")
            return
        }
        #expect(ids.count == 1)
    }

    @Test func unreadablePictureDoesNotFallBackToText() async {
        let broken = NSItemProvider(item: Data([0x00, 0x01, 0x02]) as NSData, typeIdentifier: UTType.png.identifier)
        let link = NSItemProvider(object: "https://example.com/cat.png" as NSString)
        #expect(await ClipboardReader.load([broken, link]) == nil)
    }

    @Test func pdfOpensAsADocumentNamedAfterTheFile() async throws {
        let pdf = UIGraphicsPDFRenderer(bounds: CGRect(x: 0, y: 0, width: 200, height: 200)).pdfData { $0.beginPage() }
        let provider = NSItemProvider(item: pdf as NSData, typeIdentifier: UTType.pdf.identifier)
        provider.suggestedName = "Boarding Pass.pdf"
        guard case .document(let url) = await ClipboardReader.load([provider]) else {
            Issue.record("Expected a document")
            return
        }
        #expect(url.lastPathComponent == "Boarding Pass.pdf")
        #expect(DocumentSource(urls: [url]).pages.count == 1)
        #expect(await ClipboardReader.load([provider], includeDocuments: false) == nil)
    }

    @Test func textAndWebLinksBecomeText() async {
        let note = NSItemProvider(object: "  Milk\nEggs  " as NSString)
        let link = NSItemProvider(object: URL(string: "https://example.com/menu")! as NSURL)
        #expect(await ClipboardReader.load([note, link]) == .text("Milk\nEggs\nhttps://example.com/menu"))
    }

    @Test func fileLinksAndEmptyClipboardPasteNothing() async {
        let file = NSItemProvider(object: URL(fileURLWithPath: "/tmp/report.docx") as NSURL)
        #expect(await ClipboardReader.load([file]) == nil)
        #expect(await ClipboardReader.load([]) == nil)
        #expect(await ClipboardReader.load([NSItemProvider(object: "   " as NSString)]) == nil)
    }

    @Test func veryLongTextIsShortened() async {
        let long = String(repeating: "a", count: ClipboardReader.maxTextLength + 50)
        guard case .text(let text) = await ClipboardReader.load([NSItemProvider(object: long as NSString)]) else {
            Issue.record("Expected text")
            return
        }
        #expect(text.count == ClipboardReader.maxTextLength + 1)
        #expect(text.hasSuffix("…"))
    }

    @Test func severalPastedPicturesBecomeOnePrint() {
        let design = Design.pastedImages(["a", "b"], style: .atkinson)
        #expect(design.blocks.count == 2)
        #expect(design.blocks.allSatisfy { $0.content.imageValue?.adjustments.style == .atkinson })
        #expect(design.margin == 0)
        #expect(design.prefersImageMode)
    }
}

private extension Data {
    func replacingOccurrences(of target: Data, with replacement: Data) -> Data {
        var result = Data()
        var index = startIndex
        while index < endIndex {
            if self[index...].starts(with: target) {
                result.append(replacement)
                index += target.count
            } else {
                result.append(self[index])
                index += 1
            }
        }
        return result
    }
}
